package com.clavis.reader;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;
public final class EmbeddedChapterChecks {
 static int checks;static void check(boolean b){checks++;if(!b)throw new AssertionError("check "+checks);}
 static byte[] atom(String type,byte[] body)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeInt(body.length+8);d.writeBytes(type);d.write(body);return b.toByteArray();}
 static List<EmbeddedChapters.Marker> parse(byte[] b)throws Exception{Path p=Files.createTempFile("reson-chapters",".bin");try{Files.write(p,b);try(FileChannel c=FileChannel.open(p)){return EmbeddedChapters.read(c);}}finally{Files.delete(p);}}
 public static void main(String[] args)throws Exception{ByteArrayOutputStream payload=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(payload);d.writeInt(0x01000000);d.writeInt(0);d.writeByte(2);d.writeLong(0);d.writeByte(7);d.writeBytes("Opening");d.writeLong(600000000);d.writeByte(7);d.writeBytes("Chapter");List<EmbeddedChapters.Marker> m=parse(atom("moov",atom("udta",atom("chpl",payload.toByteArray()))));check(m.size()==2);check(m.get(1).time==60000);check(m.get(0).title.equals("Opening"));byte[] title=atom("TIT2",new byte[]{3,'T','e','s','t'});ByteArrayOutputStream chap=new ByteArrayOutputStream();d=new DataOutputStream(chap);d.writeBytes("c1");d.writeByte(0);d.writeInt(12000);d.writeInt(25000);d.writeInt(-1);d.writeInt(-1);d.write(title);byte[] frame=atom("CHAP",chap.toByteArray());/* ID3 uses size, id, flags rather than atom ordering. */ByteArrayOutputStream tag=new ByteArrayOutputStream();d=new DataOutputStream(tag);d.writeBytes("CHAP");d.writeInt(chap.size());d.writeShort(0);byte[] raw=chap.toByteArray();/* replace embedded TIT2 atom with an ID3 frame */ByteArrayOutputStream nested=new ByteArrayOutputStream();DataOutputStream nd=new DataOutputStream(nested);nd.writeBytes("TIT2");nd.writeInt(5);nd.writeShort(0);nd.write(new byte[]{3,'T','e','s','t'});ByteArrayOutputStream full=new ByteArrayOutputStream();full.write(raw,0,19);full.write(nested.toByteArray());tag.reset();d=new DataOutputStream(tag);d.writeBytes("CHAP");d.writeInt(full.size());d.writeShort(0);d.write(full.toByteArray());ByteArrayOutputStream file=new ByteArrayOutputStream();file.write(new byte[]{'I','D','3',3,0,0,0,0,(byte)(tag.size()>>7),(byte)(tag.size()&127)});file.write(tag.toByteArray());m=parse(file.toByteArray());check(m.size()==1);check(m.get(0).time==12000);check(m.get(0).title.equals("Test"));check(parse(new byte[20]).isEmpty());System.out.println(checks+" chapter marker checks passed");}
}
